        self.id = id
        self.name = name
        self.email = email


class MockDatabase:
    """Simulated database for demonstration."""
    def __init__(self):
        self.users = [
            ExampleUser(1, "Alice", "alice@example.com"),
            ExampleUser(2, "Bob", "bob@example.com"),
            ExampleUser(3, "Charlie", "charlie@example.com"),
        ]

    def find_user(self, user_id: int) -> ExampleUser | None:
        for user in self.users:
            if user.id == user_id:
                return user
        return None

    def find_users_by_name(self, name_pattern: str) -> List[ExampleUser]:
        return [u for u in self.users if name_pattern.lower() in u.name.lower()]

    def find_all_users(self) -> List[ExampleUser]:
        return self.users.copy()


def bootstrap_redis_cache(config: Dict[str, Any]) -> RedisCache:
    """Create a Redis cache instance from configuration."""
    # Example config:
    # {
    #     "redis_url": "redis://localhost:6379/0",
    #     "prefix": "myapp",
    #     "default_ttl": 3600,
    #     "serializer": "json"  # or "pickle"
    # }

    default_ttl = config.get("default_ttl", 3600)
    prefix = config.get("prefix", "myapp")
    serializer_name = config.get("serializer", "json")

    from json import JSONEncoder

    if serializer_name == "json":
        from redis_cache.cache import JsonSerializer as SJ
        serializer = SJ()
    elif serializer_name == "pickle":
        from redis_cache.cache import PickleSerializer as SP
        serializer = SP()
    else:
        serializer = SJ()

    return RedisCache(
        redis_url=config.get("redis_url", "redis://localhost:6379/0"),
        prefix=prefix,
        default_ttl=default_ttl,
        serializer=serializer,
